font<-'Microsoft YaHei';tx<-function(size=10.5,bold=FALSE,col='#000000')fp_text(font.size=size,font.family=font,eastasia.family=font,hansi.family=font,color=col,bold=bold)
p<-function(s,bold=FALSE,size=10.5){doc<<-body_add_fpar(doc,fpar(ftext(s,tx(size,bold)),fp_p=fp_par(line_spacing=1.16)),style='Normal')}
h<-function(s,level=1){doc<<-body_add_fpar(doc,fpar(ftext(s,tx(if(level==1)16 else 12.5,TRUE)),fp_p=fp_par(keep_with_next=TRUE)),style=if(level==1)'heading 1'else'heading 2')}
br<-function(){doc<<-body_add_break(doc)}
tabno<-0;figno<-0
tbl<-function(x,caption,widths=NULL){tabno<<-tabno+1;doc<<-body_add_fpar(doc,fpar(ftext(paste0('表 ',tabno,'  ',caption),tx(10.5,TRUE)),fp_p=fp_par(keep_with_next=TRUE)))
 if('metric'%in%names(x)){x$metric<-c('基础 AUC','扩展 AUC','Brier 评分','校准截距','校准斜率','观察事件率','平均预测风险','AUC 增量')[seq_len(nrow(x))]}
 if('covariance'%in%names(x))x$covariance<-ifelse(x$covariance=='zero','假设协方差为 0','外部表型相关敏感性')
 for(n in names(x))if(is.numeric(x[[n]])){v<-x[[n]];s<-formatC(v,digits=3,format='fg',flag='#');ii<-is.finite(v)&v==round(v);s[ii]<-format(round(v[ii]),scientific=FALSE,trim=TRUE);x[[n]]<-ifelse(is.na(v),'—',s)}
 dict<-c(period='时期',adult_positive_fasting_nonpregnant='非妊娠空腹成人',score_complete='分数完整',eligible_score='验证纳入',metric='指标',estimate='估计',lower='下限',upper='上限',term='模型项',coefficient='系数',comparison='对比',n_control='对照',n_case='病例',genes='基因数',FDR05='FDR<0.05',FDR05_FC05='FDR及效应阈值',up='上调',down='下调',gene='基因',logFC='log2FC',P.Value='P',adj.P.Val='BH FDR',pathway='Hallmark 集合',Direction='方向',NGenes='集合基因数',outcome='结局',exposure='暴露',covariance='协方差假设',F_conditional='条件 F',variable='变量',Rhat_chain_means='链均值 R-hat',iterations='迭代数',chains='插补链',marker='指数',n='样本量',events='事件',NRI_low='NRI 下限',NRI_high='NRI 上限',C_base='基础 C',C_extended='扩展 C',delta='增量',delta_lower='增量下限',delta_upper='增量上限',candidates='显著候选',LD_independent='LD 独立工具')
 ix<-match(names(x),names(dict));names(x)[!is.na(ix)]<-unname(dict[ix[!is.na(ix)]])
 ft<-flextable(x);ft<-font(ft,fontname=font,part='all');ft<-fontsize(ft,size=9,part='all');ft<-bold(ft,part='header');ft<-bg(ft,bg='#294e64',part='header');ft<-color(ft,color='white',part='header');ft<-color(ft,color='black',part='body');if(nrow(x)>=2)ft<-bg(ft,i=seq(2,nrow(x),2),bg='#f1f4f6',part='body');ft<-padding(ft,padding=4,part='all');ft<-valign(ft,valign='center',part='all');ft<-border_remove(ft);bd<-fp_border(color='#D9D9D9',width=.5);ft<-border_outer(ft,border=bd,part='all');ft<-border_inner_h(ft,border=bd,part='all');ft<-border_inner_v(ft,border=bd,part='all');ft<-set_table_properties(ft,layout='fixed',width=1,opts_word=list(split=TRUE,repeat_headers=TRUE));if(!is.null(widths))ft<-width(ft,j=seq_along(widths),width=widths)
 doc<<-body_add_flextable(doc,ft);p(' ',size=3)}
img<-function(file,caption,maxheight=6){path<-if(file.exists(file))file else file.path(out,file);if(!file.exists(path))stop(path);co<-file(path,'rb');readBin(co,'raw',16);dim<-readBin(co,'integer',2,size=4,endian='big');close(co);wi<-6.65;he<-wi*dim[2]/dim[1];if(he>maxheight){wi<-wi*maxheight/he;he<-maxheight};doc<<-body_add_img(doc,src=path,width=wi,height=he);figno<<-figno+1;p(paste0('图 ',figno,'  ',caption),size=9.5)}
fmt<-function(x)sprintf('%.3f',x);pv<-function(x)ifelse(is.na(x),'—',ifelse(x<.001,'<0.001',sprintf('%.3f',x)))
hrtab<-function(x,first){data.frame(分析=first,样本量=x$n,事件=x$events,HR=sprintf('%.3f',x$HR),`95% CI`=sprintf('%.3f–%.3f',x$lower,x$upper),P=pv(x$p),check.names=FALSE)}
p('CMIBI 死亡关联与多组学重分析报告',TRUE,23)
p('供重新撰写论文使用的完整统计与方法报告',size=14)
p('2026 年 10 月 16 日',size=11)
p('本报告汇总数据核验、复杂抽样生存分析、多重插补、历史独立参与者验证、转录组重处理、LD 去相关后的孟德尔随机化以及脂质多变量 MR。所有主表与图使用本轮重算结果。')
p('主要结论',TRUE,13)
p('修正后的 CMIBI 与心血管死亡相关；多重插补与独立历史时期验证支持该关联。全因死亡结果对缺失数据处理敏感，癌症死亡关联仍不明确。独立验证中的十年 AUC 增量置信区间跨 0，因此不能宣称临床预测优越性。转录组并不支持所有人群均有一致炎症上调。MR 支持部分风险成分的关联，同时检出显著异质性与多效性，不能据此证明复合 CMIBI 的因果效应。')
p('建议将论文主线定位为观察性关联及历史时期验证，将转录组、预测增量和 MR 放在明确标注的补充证据层。该报告不是投稿排版终稿，作者与资助等事实信息仍由作者填写。')
tbl(data.frame(模块=c('主队列','多重插补','历史验证','转录组','单变量 MR','多变量 MR'),完成内容=c('原始值与死因核对；修正变量和校准；M1–M4、敏感性及诊断','30 份插补，每份 20 次迭代；Rubin 合并及收敛核查','1999–2004 独立参与者；固定量尺；锁定十年模型、AUC 与校准','检查处理尺度；limma；年龄/性别调整；分开 T1D/T2D；camera 通路','1000G EUR LD clumping；10 个主检验；Steiger、PRESSO、留一法','HDL、TG、LDL 联合工具；条件 F 与协方差敏感性')),'本轮完成范围',c(1.0,5.65))
br();h('1 数据来源与分析边界')
p('主队列为 NHANES 2005–2006、2007–2008、2009–2010、2015–2016、2017–2018，死亡链接截至 2019 年末。历史验证使用未参与主队列的 1999–2000、2001–2002、2003–2004；已核实与开发样本 SEQN 无交集。所有原始数据保持不变。')
p('先前报告中的手工实现和部分变量定义存在问题。本轮从原始 XPT 重新提取用药与活动信息，对其余分数原始值、逐次血压与死亡 DAT 进行了 120 项逐周期核对，差异为 0；CRP 单位另行逐周期核对。缺失的历史文件从 CDC 官方地址补充下载，保存在任务目录。')
tbl(data.frame(问题=c('降糖药','降压药','体力活动','CRP','肌酐与 eGFR','2017–2018 生化','随访与链接'),本轮处理=c('DIQ050 胰岛素，加 DID070/DIQ070 药片；不使用 DIQ080/DIQ160 作为药物','使用 BPQ050A 当前服药，结合明确的跳题链','按周期选择 PAD200/PAD320 或 PAQ650/PAQ665，保留真实缺失','统一 mg/L；原代码实际上已统一 mg/dL，不再重复十倍校正','2005–2006 校准；使用无种族项 CKD-EPI 2021','白蛋白、ALP、尿酸及肌酐按 CDC backward equations 桥接','PERMTH_EXM；ELIGSTAT=1；正空腹权重；正随访')),'关键修正',c(1.15,5.5))
p('NHANES 的公开死亡文件包含扰动处理，死因和随访必须按其官方定义解释。研究为观察性二次分析，不能识别个体治疗效果。')
